begin;
do $curate$ declare bid uuid;begin
if exists(select 1 from businesses where website ilike '%www.californiapetgroomingmobile.com%' or lower(name)=lower('California Pet Grooming Mobile') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%2094878400') then raise exception 'Duplicate requires review';end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('California Pet Grooming Mobile','Pet Services','Manteca',null,'(209) 487-8400','https://www.californiapetgroomingmobile.com/','Advertises mobile dog grooming and explicitly lists Mountain House, Tracy, Lathrop and Manteca. The official website publishes this contact number and links to an appointment-request system. Confirm your service address, dog requirements, quote and appointment directly; a displayed request does not confirm availability. Public visitor office not established.','approved',true,false,null,0,'editorial_first_party','https://www.californiapetgroomingmobile.com/#service-area','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.californiapetgroomingmobile.com/#service-area',array['identity','website','public phone','mobile dog grooming','named service cities','eligibility limitations'],array['Mountain House','Tracy','Lathrop','Manteca'],array['mobile dog grooming','dog grooming'],'Website information check November 8, 2026: identity, advertised mobile dog grooming, published phone, named service cities and stated eligibility limits. No owner confirmation, license/insurance/quality/safety check, photo rights, price or appointment endorsement. Sources: https://www.californiapetgroomingmobile.com/ https://www.californiapetgroomingmobile.com/#service-area. Advertises mobile dog grooming and explicitly lists Mountain House, Tracy, Lathrop and Manteca. The official website publishes this contact number and links to an appointment-request system. Confirm your service address, dog requirements, quote and appointment directly; a displayed request does not confirm availability. Public visitor office not established.');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "California Pet Grooming Mobile", "city": "Manteca", "phone": "(209) 487-8400", "website": "https://www.californiapetgroomingmobile.com/", "source_url": "https://www.californiapetgroomingmobile.com/#service-area", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "description": "Advertises mobile dog grooming and explicitly lists Mountain House, Tracy, Lathrop and Manteca. The official website publishes this contact number and links to an appointment-request system. Confirm your service address, dog requirements, quote and appointment directly; a displayed request does not confirm availability. Public visitor office not established."}'::jsonb,'Mobile-grooming coverage expansion with explicit city limits','https://www.californiapetgroomingmobile.com/#service-area');end $curate$;
do $curate$ declare bid uuid;begin
if exists(select 1 from businesses where website ilike '%anasmobilegrooming.com%' or lower(name)=lower('Ana''s Mobile Dog Grooming') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%3502263247') then raise exception 'Duplicate requires review';end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Ana''s Mobile Dog Grooming','Pet Services','Riverbank',null,'(350) 226-3247','https://anasmobilegrooming.com/','Riverbank-based mobile dog groomer whose FAQ names Lathrop and Manteca. It excludes new clients in Mountain House and Tracy, does not serve apartment complexes, requires two street-parking spaces and lists a 60-pound dog limit. Confirm address eligibility, dog requirements, quote and current appointment availability directly.','approved',true,false,null,0,'editorial_first_party','https://anasmobilegrooming.com/faq','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://anasmobilegrooming.com/faq',array['identity','website','public phone','mobile dog grooming','named service cities','eligibility limitations'],array['Lathrop','Manteca'],array['mobile dog grooming','dog grooming'],'Website information check November 8, 2026: identity, advertised mobile dog grooming, published phone, named service cities and stated eligibility limits. No owner confirmation, license/insurance/quality/safety check, photo rights, price or appointment endorsement. Sources: https://anasmobilegrooming.com/ https://anasmobilegrooming.com/faq. Riverbank-based mobile dog groomer whose FAQ names Lathrop and Manteca. It excludes new clients in Mountain House and Tracy, does not serve apartment complexes, requires two street-parking spaces and lists a 60-pound dog limit. Confirm address eligibility, dog requirements, quote and current appointment availability directly.');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Ana''s Mobile Dog Grooming", "city": "Riverbank", "phone": "(350) 226-3247", "website": "https://anasmobilegrooming.com/", "source_url": "https://anasmobilegrooming.com/faq", "areas": ["Lathrop", "Manteca"], "description": "Riverbank-based mobile dog groomer whose FAQ names Lathrop and Manteca. It excludes new clients in Mountain House and Tracy, does not serve apartment complexes, requires two street-parking spaces and lists a 60-pound dog limit. Confirm address eligibility, dog requirements, quote and current appointment availability directly."}'::jsonb,'Mobile-grooming coverage expansion with explicit city limits','https://anasmobilegrooming.com/faq');end $curate$;
do $rename$ begin
if not exists(select 1 from businesses where id='50b70a38-4a16-44e4-8ba3-feaa10231ff1'::uuid and name='Bayberry Grooming' and website='https://www.bayberrygrooming.com/') then raise exception 'Existing brand record changed; review before update';end if;
if exists(select 1 from businesses where id<>'50b70a38-4a16-44e4-8ba3-feaa10231ff1'::uuid and website ilike '%iluvmypack.com%') then raise exception 'Rebrand duplicate requires review';end if;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) select b.id,jsonb_build_object('name',b.name,'website',b.website,'description',b.description,'source_url',b.source_url,'check',(select to_jsonb(c) from listing_checks c where c.business_id=b.id)),'{"id": "50b70a38-4a16-44e4-8ba3-feaa10231ff1", "name": "iLuvMyPack Mobile Grooming (formerly Bayberry Grooming)", "website": "https://www.iluvmypack.com/", "description": "The official iLuvMyPack site identifies its former name as Bayberry Grooming and explicitly lists Mountain House, Tracy, Lathrop and Manteca for mobile dog grooming. It offers new-client intake with availability dependent on existing routes. Confirm address eligibility, dog needs, quote and appointments directly; public phone and visitor office not established."}'::jsonb,'Official site identifies former Bayberry name; preserve existing identity and links','https://www.iluvmypack.com/' from businesses b where b.id='50b70a38-4a16-44e4-8ba3-feaa10231ff1'::uuid;
update businesses set name='iLuvMyPack Mobile Grooming (formerly Bayberry Grooming)',website='https://www.iluvmypack.com/',description='The official iLuvMyPack site identifies its former name as Bayberry Grooming and explicitly lists Mountain House, Tracy, Lathrop and Manteca for mobile dog grooming. It offers new-client intake with availability dependent on existing routes. Confirm address eligibility, dog needs, quote and appointments directly; public phone and visitor office not established.',source_url='https://www.iluvmypack.com/',verification_source='first_party_website_desk_check',verified_at=now(),updated_at=now() where id='50b70a38-4a16-44e4-8ba3-feaa10231ff1'::uuid;
update listing_checks set checked_at=now(),source_url='https://www.iluvmypack.com/',checked_fields=array['website identity and former brand','mobile dog grooming','named service cities','intake and route limits'],service_areas=array['Mountain House','Tracy','Lathrop','Manteca'],scope_note='Website information rechecked November 8, 2026. Official iLuvMyPack site explicitly identifies former Bayberry name and all four service cities. Existing listing ID preserved to avoid duplicate operators. Intake and route-dependent availability are not confirmed appointments; no public phone, visitor office, owner/ownership-transfer, credentials, quality or photo rights confirmed.' where business_id='50b70a38-4a16-44e4-8ba3-feaa10231ff1'::uuid;end $rename$;
commit;
